      "reason": "The abstract explicitly labels the work as a 'systematic review and meta-analysis', identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Accuracy of novel antigen rapid diagnostics for SARS-CoV-2: A living systematic review and metaanalysis.",
      "reason": "The title specifies the topic and target of the review — accuracy of antigen rapid diagnostics for SARS-CoV-2 — which provides key information about the intervention/exposure and condition under study."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Accuracy of novel antigen rapid diagnostics for SARS-CoV-2: A living systematic review and metaanalysis.",
      "reason": "The title includes 'meta-analysis' (analysis method) and 'living' (living-review status), providing relevant supplementary information about the review format and update status."
    }
  ],
  "confidence": 85
